-- Static company facts (description, employee count, headquarters) shown in the company snapshot.
-- These rarely change, so they live here instead of being fetched from an API on every view.
-- Employee counts are approximate, from each company's most recent annual report (2024-2025).
-- Edit rows directly to update them; add a row when adding a new stock.
CREATE TABLE IF NOT EXISTS public.company_profiles (
  ticker text PRIMARY KEY,
  description text NOT NULL,
  full_time_employees integer,
  city text,
  state text,
  country text NOT NULL DEFAULT 'US',
  updated_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.company_profiles ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Company profiles are readable by everyone" ON public.company_profiles;
CREATE POLICY "Company profiles are readable by everyone"
  ON public.company_profiles FOR SELECT
  USING (true);

ON CONFLICT (ticker) DO UPDATE SET
  description = EXCLUDED.description,
  full_time_employees = EXCLUDED.full_time_employees,
  city = EXCLUDED.city,
  state = EXCLUDED.state,
  country = EXCLUDED.country,
  updated_at = now();
